with current_programs as(select id,to_jsonb(x) j from public.affiliate_program_master x),current_drafts as(select program_master_id id,to_jsonb(x) j from public.affiliate_program_drafts x),mismatch as(
 select count(*) n from _m030_recovery.program_rows b full join current_programs c using(id) where b.id is null or c.id is null or b.row_hash<>encode(extensions.digest(c.j::text,'sha256'),'hex')
 union all select count(*) from _m030_recovery.draft_rows b full join current_drafts c on c.id=b.program_master_id where b.program_master_id is null or c.id is null or b.row_hash<>encode(extensions.digest(c.j::text,'sha256'),'hex'))
select jsonb_build_object('result',case when (select count(*) from _m030_recovery.control where state='SEALED')=1 and (select sum(n) from mismatch)=0 and not has_schema_privilege('anon','_m030_recovery','USAGE') and not has_schema_privilege('authenticated','_m030_recovery','USAGE') and not has_schema_privilege('service_role','_m030_recovery','USAGE') then 'M030_RECOVERY_VERIFICATION_PASS' else 'FAIL' end,'program_rows',(select count(*) from _m030_recovery.program_rows),'draft_rows',(select count(*) from _m030_recovery.draft_rows),'row_mismatches',(select sum(n) from mismatch)) verification;
